  "Энэ бичиг ямар болзлоор олгогдов:": "本证书颁发条件：",
  "Энэ бодлогод өөрчлөлт орвол энэ хуудсан дээр шинэчилж, огноог тэмдэглэнэ.": "本政策如有变更，将在本页更新并注明日期。",
  "Энэ бол «Бөөндөө Сурцгаая» аппын сургалтын бүртгэлээс гаргасан курс дүүргэлтийн бичиг. Энэ нь улсын болон олон улсын шалгалтын гэрчилгээ биш, HSK-ийн албан ёсны түвшин баталгаажуулсан бичиг биш, ямар нэг магадлан итгэмжлэлийн үнэлгээ илэрхийлэхгүй.": "这是根据«Бөөндөө Сурцгаая»应用学习记录生成的课程结业证明。它不是国家或国际考试证书，也不是 HSK 官方等级认证，不代表任何资质认证评估。",
  "Энэ бол нэг сурагчид онилж өгсөн даалгавар. Ангийн бусад сурагчид үүнийг огт харахгүй — доорх жагсаалтад бүх сурагч харагдах ч ажиллах мөр зөвхөн зорилтот сурагчид үүссэн.": "这是单独布置给一名学生的作业。班级其他学生完全看不到 — 下方列表虽显示全部学生，但只为目标学生生成了作业记录。",
  "Энэ бол шалгалт биш. Хариулт сонгонгуут зөв нь ямар байсныг шууд харуулна. Сонсголын аудиог хэдэн ч удаа сонсож болно.": "这不是考试。选择答案后会立即显示正确答案。听力音频可反复收听。",
